/** Engine hit-location order, as region names used by this engine. */
export const HIT_LOCATION_ORDER = ['head', 'leftArm', 'rightArm', 'torso', 'rightLeg', 'leftLeg', 'eyes', 'groin', 'uncalled'] as const

export function hitLocationIndex(region: string): number {
    const idx = (HIT_LOCATION_ORDER as readonly string[]).indexOf(region)
    return idx >= 0 ? idx : 3
}
